 42	function formatDate(timestamp: number): string {
 43	  const date = new Date(timestamp);
 44	  const now = new Date();
 45	  const isToday = date.toDateString() === now.toDateString();
 46	
 47	  const time = date.toLocaleTimeString('zh-CN', {
 48	    hour: '2-digit',
 49	    minute: '2-digit',
 50	  });
 51	
 52	  if (isToday) {
 53	    return `今天 ${time}`;
 54	  }
 55	
 56	  return date.toLocaleDateString('zh-CN', {
 57	    month: 'short',
 58	    day: 'numeric',
 59	    hour: '2-digit',
 60	    minute: '2-digit',
 61	  });
 62	}
 63	
 64	function getScoreColor(score: number): string {
 65	  if (score >= 8) return 'text-green-600';
 66	  if (score >= 6) return 'text-yellow-600';
 67	  return 'text-red-600';
 68	}
