 70	export const ReviewHistoryDialog = memo<ReviewHistoryDialogProps>(
 71	  ({ open, onOpenChange, tableNormalizedName }) => {
 72	    const [reviews, setReviews] = useState<ReviewRecordMetadata[]>([]);
 73	    const [loading, setLoading] = useState(false);
