 79	    const [actionLoading, setActionLoading] = useState(false);
 80	
 81	    // 加载评审列表
 82	    const loadReviews = useCallback(async () => {
 83	      setLoading(true);
 84	      try {
 85	        const list = await listReviewMetadata(tableNormalizedName || undefined);
 86	        setReviews(list);
 87	      } finally {
 88	        setLoading(false);
 89	      }
 90	    }, [tableNormalizedName]);
 91	
 92	    useEffect(() => {
 93	      if (open) {
 94	        loadReviews();
 95	      } else {
 96	        setReviews([]);
 97	        setExpandedId(null);
 98	        setExpandedDetail(null);
 99	      }
100	    }, [open, loadReviews]);
101	
102	    // 展开/折叠详情
