152	                reviews.map((r) => (
153	                  <div
154	                    key={r.id}
155	                    className="group rounded-lg border bg-muted/30 transition-colors hover:bg-muted/50"
156	                  >
157	                    <div className="relative">
158	                      <button
159	                        type="button"
160	                        onClick={() => handleToggleExpand(r.id)}
161	                        className="flex w-full cursor-pointer items-start gap-3 rounded-lg p-3 text-left outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
162	                      >
163	                        <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-primary/10">
164	                          <Star
165	                            className={cn('h-4 w-4', getScoreColor(r.score))}
166	                          />
167	                        </span>
168	                        <span className="min-w-0 flex-1">
169	                          <span className="flex items-center gap-2">
170	                            <span
171	                              className={cn(
172	                                'text-lg font-semibold',
173	                                getScoreColor(r.score),
174	                              )}
175	                            >
176	                              {r.score}/10
177	                            </span>
178	                            <span className="text-xs text-muted-foreground">
179	                              {formatDate(r.createdAt)}
180	                            </span>
181	                          </span>
182	                          <span className="mt-0.5 block truncate text-sm text-muted-foreground">
183	                            {r.tableName} · {r.dbType.toUpperCase()}
184	                          </span>
185	                          <span className="mt-1 line-clamp-2 block text-xs text-foreground/80">
186	                            {r.summary}
187	                          </span>
188	                        </span>
189	                        <span className="flex shrink-0 items-center gap-1 pr-8">
190	                          {expandedId === r.id ? (
191	                            <ChevronUp className="h-4 w-4 text-muted-foreground" />
192	                          ) : (
193	                            <ChevronDown className="h-4 w-4 text-muted-foreground" />
194	                          )}
195	                        </span>
196	                      </button>
197	
198	                      <Button
199	                        variant="ghost"
200	                        size="icon"
201	                        className="absolute right-3 top-3 h-7 w-7 opacity-0 transition-opacity group-hover:opacity-100"
202	                        onClick={(e) => {
