 40	function formatDate(timestamp: number): string {
 41	  const date = new Date(timestamp);
 42	  const now = new Date();
 43	  const isToday = date.toDateString() === now.toDateString();
 44	
 45	  const time = date.toLocaleTimeString('zh-CN', {
 46	    hour: '2-digit',
 47	    minute: '2-digit',
 48	  });
 49	
 50	  if (isToday) {
 51	    return `今天 ${time}`;
 52	  }
 53	
 54	  return date.toLocaleDateString('zh-CN', {
 55	    month: 'short',
 56	    day: 'numeric',
 57	    hour: '2-digit',
 58	    minute: '2-digit',
 59	  });
 60	}
