 27	type ImportStep = 'validate' | 'preview' | 'confirm';
 28	
 29	interface ImportSqlDialogProps {
 30	  currentDbType: DatabaseType;
 31	  onImport: (result: ParsedResult, dbType: DatabaseType) => void;
 32	  triggerClassName?: string;
 33	  triggerIcon?: ReactNode;
