 37	const MAX_SQL_LENGTH = 50_000;
 38	const SQL_PARSE_ERROR_MESSAGE = 'SQL 解析失败，请检查 SQL 语法后重试。';
 39	
 40	export function ImportSqlDialog({
 41	  currentDbType,
 42	  onImport,
 43	  triggerClassName,
 44	  triggerIcon,
 45	  triggerLabel = '导入 SQL',
 46	}: ImportSqlDialogProps) {
 47	  const [open, setOpen] = useState(false);
 48	  const [step, setStep] = useState<ImportStep>('validate');
 49	  const [sql, setSql] = useState('');
 50	  const [selectedDbType, setSelectedDbType] =
 51	    useState<DatabaseType>(currentDbType);
 52	  const [parsedResult, setParsedResult] = useState<ParsedResult | null>(null);
 53	  const [validationResult, setValidationResult] =
 54	    useState<ValidationResult | null>(null);
 55	  const [isValidating, setIsValidating] = useState(false);
 56	  const [previewFields, setPreviewFields] = useState<PreviewField[]>([]);
 57	  const { showToast } = useToast();
 58	
 59	  useEffect(() => {
 60	    if (!open) {
 61	      setStep('validate');
 62	      setSql('');
 63	      setParsedResult(null);
 64	      setValidationResult(null);
 65	      setPreviewFields([]);
 66	    }
 67	  }, [open]);
 68	
 69	  const validateSql = useCallback(async () => {
 70	    const trimmedSql = sql.trim();
 71	    if (!trimmedSql) {
 72	      setValidationResult({
 73	        success: false,
 74	        error: 'SQL 内容不能为空',
 75	        lineNumber: 1,
 76	      });
 77	      return;
 78	    }
 79	
 80	    if (trimmedSql.length > MAX_SQL_LENGTH) {
 81	      setValidationResult({
 82	        success: false,
 83	        error: `SQL 内容过长，最大允许 ${MAX_SQL_LENGTH.toLocaleString()} 个字符`,
 84	        lineNumber: 1,
 85	      });
 86	      return;
 87	    }
 88	
 89	    setIsValidating(true);
 90	    setValidationResult(null);
 91	
 92	    try {
 93	      const result = await requestSqlParse({
 94	        sql: trimmedSql,
 95	        dbType: selectedDbType,
 96	      });
 97	
 98	      if (result.fields.length === 0 && result.tableName === '') {
 99	        setValidationResult({
100	          success: false,
101	          error: '未能从 SQL 中解析出有效的表结构，请检查 SQL 语法。',
102	        });
103	        setIsValidating(false);
104	        return;
105	      }
106	
107	      setValidationResult({ success: true });
108	      setParsedResult(result);
109	
110	      const fields: PreviewField[] = result.fields.map((field, index) => ({
111	        order: index + 1,
112	        fieldName: field.name,
113	        fieldType: field.type,
114	        fieldComment: field.comment,
115	        nullable: field.nullable ? '是' : '否',
116	        defaultKind:
117	          field.defaultKind === 'none'
118	            ? '无'
119	            : field.defaultKind === 'auto_increment'
120	              ? '自增'
121	              : field.defaultKind === 'constant'
122	                ? '常量'
123	                : field.defaultKind === 'current_timestamp'
124	                  ? '当前时间'
125	                  : 'uuid',
126	        defaultValue: field.defaultValue || '-',
127	      }));
128	      setPreviewFields(fields);
129	      setStep('preview');
130	    } catch {
131	      setValidationResult({
132	        success: false,
133	        error: SQL_PARSE_ERROR_MESSAGE,
134	      });
135	    } finally {
136	      setIsValidating(false);
137	    }
138	  }, [sql, selectedDbType]);
139	
140	  const handleNext = () => {
141	    if (step === 'validate') {
142	      validateSql();
143	    } else if (step === 'preview') {
144	      setStep('confirm');
145	    }
146	  };
147	
148	  const handleBack = () => {
149	    if (step === 'preview') {
150	      setStep('validate');
151	    } else if (step === 'confirm') {
152	      setStep('preview');
153	    }
154	  };
155	
156	  const handleConfirm = () => {
157	    if (!parsedResult) return;
158	
159	    onImport(parsedResult, selectedDbType);
160	    setOpen(false);
161	    setSql('');
162	    setParsedResult(null);
163	    setValidationResult(null);
164	    setPreviewFields([]);
165	    setStep('validate');
166	    showToast(`导入成功: 成功解析表: ${parsedResult.tableName || '未命名'}`);
167	  };
168	
169	  const handleFieldChange = (
170	    index: number,
171	    field: keyof PreviewField,
172	    value: string | number,
173	  ) => {
174	    setPreviewFields((prev) => {
175	      const newFields = [...prev];
176	      newFields[index] = { ...newFields[index], [field]: value };
177	      return newFields;
178	    });
179	  };
180	
181	  const moveField = (index: number, direction: 'up' | 'down') => {
182	    const newIndex = direction === 'up' ? index - 1 : index + 1;
183	    if (newIndex < 0 || newIndex >= previewFields.length) return;
184	
185	    setPreviewFields((prev) => {
186	      const newFields = [...prev];
187	      [newFields[index], newFields[newIndex]] = [
188	        newFields[newIndex],
189	        newFields[index],
190	      ];
191	      return newFields;
192	    });
193	  };
194	
195	  const deleteField = (index: number) => {
196	    setPreviewFields((prev) => prev.filter((_, i) => i !== index));
197	  };
198	
199	  return (
200	    <Dialog open={open} onOpenChange={setOpen}>
201	      <Tooltip>
202	        <TooltipTrigger asChild>
203	          <DialogTrigger asChild>
204	            <button type="button" className={triggerClassName}>
205	              {triggerIcon}
206	              <span>{triggerLabel}</span>
207	            </button>
208	          </DialogTrigger>
209	        </TooltipTrigger>
210	        <TooltipContent>
211	          <p>导入 SQL 自动生成表结构</p>
212	        </TooltipContent>
213	      </Tooltip>
214	      <DialogContent className="sm:max-w-[700px]">
215	        <DialogHeader>
216	          <DialogTitle>导入 SQL</DialogTitle>
217	          <DialogDescription>
218	            粘贴 CREATE TABLE 语句以自动生成表结构配置。
219	          </DialogDescription>
220	        </DialogHeader>
221	
222	        {/* Stepper */}
223	        <div className="flex items-center justify-center py-4">
224	          <div className="flex items-center gap-2">
225	            {/* 步骤 1: 校验 */}
226	            <div
227	              className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-sm font-medium transition-all duration-200 ${
228	                step === 'validate'
229	                  ? 'bg-primary text-primary-foreground shadow-md ring-2 ring-primary/20'
230	                  : step === 'preview' || step === 'confirm'
231	                    ? 'bg-green-100 text-green-700 border border-green-200'
232	                    : 'bg-muted text-muted-foreground border border-border'
233	              }`}
234	            >
235	              <span
236	                className={`flex h-5 w-5 items-center justify-center rounded-full text-xs ${
237	                  step === 'validate'
238	                    ? 'bg-primary-foreground/20'
239	                    : step === 'preview' || step === 'confirm'
240	                      ? 'bg-green-500 text-white'
241	                      : 'bg-muted-foreground/20'
242	                }`}
243	              >
244	                {step === 'preview' || step === 'confirm' ? (
245	                  <Check className="h-3 w-3" />
246	                ) : (
247	                  '1'
248	                )}
249	              </span>
250	              校验
251	            </div>
252	            <div
253	              className={`h-0.5 w-8 transition-colors ${
254	                step === 'preview' || step === 'confirm'
255	                  ? 'bg-green-400'
256	                  : 'bg-border'
257	              }`}
258	            />
259	            {/* 步骤 2: 预览 */}
260	            <div
261	              className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-sm font-medium transition-all duration-200 ${
262	                step === 'preview'
263	                  ? 'bg-primary text-primary-foreground shadow-md ring-2 ring-primary/20'
264	                  : step === 'confirm'
265	                    ? 'bg-green-100 text-green-700 border border-green-200'
266	                    : 'bg-muted text-muted-foreground border border-border'
267	              }`}
268	            >
269	              <span
270	                className={`flex h-5 w-5 items-center justify-center rounded-full text-xs ${
271	                  step === 'preview'
272	                    ? 'bg-primary-foreground/20'
273	                    : step === 'confirm'
274	                      ? 'bg-green-500 text-white'
275	                      : 'bg-muted-foreground/20'
276	                }`}
277	              >
278	                {step === 'confirm' ? <Check className="h-3 w-3" /> : '2'}
279	              </span>
280	              预览
281	            </div>
282	            <div
283	              className={`h-0.5 w-8 transition-colors ${
284	                step === 'confirm' ? 'bg-green-400' : 'bg-border'
285	              }`}
286	            />
287	            {/* 步骤 3: 确认 */}
288	            <div
289	              className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-sm font-medium transition-all duration-200 ${
290	                step === 'confirm'
291	                  ? 'bg-primary text-primary-foreground shadow-md ring-2 ring-primary/20'
292	                  : 'bg-muted text-muted-foreground border border-border'
293	              }`}
294	            >
295	              <span
296	                className={`flex h-5 w-5 items-center justify-center rounded-full text-xs ${
297	                  step === 'confirm'
298	                    ? 'bg-primary-foreground/20'
299	                    : 'bg-muted-foreground/20'
300	                }`}
301	              >
302	                3
303	              </span>
304	              确认
305	            </div>
306	          </div>
307	        </div>
308	
309	        {/* Step Content */}
310	        <div className="grid gap-4 py-4">
311	          {step === 'validate' && (
312	            <SqlInputStep
313	              selectedDbType={selectedDbType}
314	              onDbTypeChange={setSelectedDbType}
315	              sql={sql}
316	              onSqlChange={setSql}
317	              validationResult={validationResult}
318	            />
319	          )}
320	
321	          {step === 'preview' && parsedResult && (
322	            <PreviewStep
323	              parsedResult={parsedResult}
324	              previewFields={previewFields}
325	              onFieldChange={handleFieldChange}
326	              onMoveField={moveField}
327	              onDeleteField={deleteField}
328	            />
329	          )}
330	
331	          {step === 'confirm' && (
332	            <ConfirmStep
333	              parsedResult={parsedResult}
334	              previewFieldCount={previewFields.length}
335	              selectedDbType={selectedDbType}
336	            />
337	          )}
338	        </div>
339	
340	        <DialogFooter>
341	          {step === 'validate' && (
342	            <>
343	              <Button variant="outline" onClick={() => setOpen(false)}>
344	                取消
345	              </Button>
346	              <Button
347	                onClick={handleNext}
348	                disabled={isValidating || !sql.trim()}
