350	                {isValidating ? '校验中...' : '下一步'}
351	              </Button>
352	            </>
353	          )}
354	          {step === 'preview' && (
355	            <>
356	              <Button variant="outline" onClick={handleBack}>
357	                上一步
358	              </Button>
359	              <Button onClick={handleNext}>
360	                下一步 <ArrowRight className="ml-2 h-4 w-4" />
