362	            </>
363	          )}
364	          {step === 'confirm' && (
365	            <>
366	              <Button variant="outline" onClick={handleBack}>
367	                上一步
368	              </Button>
369	              <Button onClick={handleConfirm}>确认导入</Button>
370	            </>
371	          )}
372	        </DialogFooter>
373	      </DialogContent>
374	    </Dialog>
375	  );
376	}

  1	/**
  2	 * 模板管理对话框组件
  3	 * 提供模板的查看、创建、编辑、删除功能，包含字段编辑器
  4	 */
  5	
  6	import { memo, useState, useCallback, useEffect, useMemo } from 'react';
  7	import { Plus, Search } from 'lucide-react';
  8	import {
  9	  Dialog,
 10	  DialogContent,
 11	  DialogDescription,
 12	  DialogFooter,
 13	  DialogHeader,
 14	  DialogTitle,
 15	} from '@/components/ui/dialog';
 16	import {
 17	  AlertDialog,
 18	  AlertDialogAction,
 19	  AlertDialogCancel,
 20	  AlertDialogContent,
 21	  AlertDialogDescription,
 22	  AlertDialogFooter,
 23	  AlertDialogHeader,
 24	  AlertDialogTitle,
 25	} from '@/components/ui/alert-dialog';
 26	import { Button } from '@/components/ui/button';
 27	import { Input } from '@/components/ui/input';
 28	import { Label } from '@/components/ui/label';
 29	import type { FieldTemplate, TemplateField } from '@/hooks/useFieldTemplates';
 30	import { FieldEditRow, createEmptyField } from './FieldEditRow';
 31	import { TemplateListItem } from './TemplateListItem';
 32	
 33	// 模板管理对话框
 34	interface TemplateManagerDialogProps {
 35	  open: boolean;
 36	  onOpenChange: (open: boolean) => void;
 37	  templates: FieldTemplate[];
 38	  loading: boolean;
 39	  onCreateTemplate: (
 40	    name: string,
 41	    fields: TemplateField[],
 42	    description?: string,
 43	  ) => Promise<{ ok: boolean }>;
 44	  onUpdateTemplate: (
 45	    id: string,
 46	    updates: Partial<Pick<FieldTemplate, 'name' | 'description' | 'fields'>>,
 47	  ) => Promise<{ ok: boolean }>;
 48	  onDuplicateTemplate: (
 49	    id: string,
 50	    newName?: string,
 51	  ) => Promise<{ ok: boolean }>;
 52	  onDeleteTemplate: (id: string) => Promise<{ ok: boolean }>;
 53	}
 54	
 55	export const TemplateManagerDialog = memo<TemplateManagerDialogProps>(
 56	  ({
 57	    open,
 58	    onOpenChange,
 59	    templates,
 60	    loading,
 61	    onCreateTemplate,
 62	    onUpdateTemplate,
 63	    onDuplicateTemplate,
 64	    onDeleteTemplate,
 65	  }) => {
 66	    const [searchTerm, setSearchTerm] = useState('');
 67	    const [editingTemplate, setEditingTemplate] =
 68	      useState<FieldTemplate | null>(null);
