 74	    const [isSaving, setIsSaving] = useState(false);
 75	
 76	    const [deleteTarget, setDeleteTarget] = useState<FieldTemplate | null>(
 77	      null,
 78	    );
 79	    const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
 80	
 81	    // 过滤模板
 82	    const filteredTemplates = useMemo(() => {
 83	      if (!searchTerm.trim()) return templates;
 84	      const term = searchTerm.toLowerCase();
 85	      return templates.filter(
 86	        (t) =>
 87	          t.name.toLowerCase().includes(term) ||
 88	          t.description?.toLowerCase().includes(term),
 89	      );
 90	    }, [templates, searchTerm]);
 91	
 92	    // 打开新建/编辑对话框
 93	    const handleOpenEditDialog = useCallback((template?: FieldTemplate) => {
 94	      if (template) {
 95	        setEditingTemplate(template);
 96	        setEditName(template.name);
 97	        setEditDescription(template.description || '');
