105	      }
106	      setEditError('');
107	      setIsSaving(false);
108	      setIsEditDialogOpen(true);
109	    }, []);
110	
111	    // 添加字段
112	    const handleAddField = useCallback(() => {
113	      setEditFields((prev) => [...prev, createEmptyField()]);
114	    }, []);
115	
116	    // 更新字段
117	    const handleFieldChange = useCallback(
118	      (index: number, field: TemplateField) => {
119	        setEditFields((prev) => {
120	          const next = [...prev];
121	          next[index] = field;
122	          return next;
123	        });
124	      },
