126	    );
127	
128	    // 删除字段
129	    const handleRemoveField = useCallback((index: number) => {
130	      setEditFields((prev) => prev.filter((_, i) => i !== index));
131	    }, []);
132	
133	    // 移动字段
134	    const handleMoveField = useCallback(
135	      (index: number, direction: 'up' | 'down') => {
136	        setEditFields((prev) => {
137	          const next = [...prev];
138	          const targetIndex = direction === 'up' ? index - 1 : index + 1;
139	          if (targetIndex < 0 || targetIndex >= next.length) return prev;
140	          [next[index], next[targetIndex]] = [next[targetIndex], next[index]];
141	          return next;
142	        });
143	      },
144	      [],
145	    );
146	
147	    // 保存模板
148	    const handleSaveTemplate = useCallback(async () => {
149	      const trimmedName = editName.trim();
150	      if (!trimmedName) {
151	        setEditError('请输入模板名称');
152	        return;
153	      }
154	
155	      // 过滤掉空字段
156	      const validFields = editFields.filter((f) => f.fieldName.trim());
157	
158	      setIsSaving(true);
159	      setEditError('');
160	
161	      try {
162	        let result: { ok: boolean };
163	        if (editingTemplate) {
164	          result = await onUpdateTemplate(editingTemplate.id, {
165	            name: trimmedName,
166	            description: editDescription.trim() || undefined,
167	            fields: validFields,
168	          });
169	        } else {
170	          result = await onCreateTemplate(
171	            trimmedName,
172	            validFields,
173	            editDescription.trim() || undefined,
174	          );
175	        }
176	
177	        if (result.ok) {
178	          setIsEditDialogOpen(false);
179	          setEditingTemplate(null);
180	        } else {
181	          setEditError('保存失败');
182	        }
183	      } finally {
184	        setIsSaving(false);
185	      }
186	    }, [
187	      editName,
188	      editDescription,
189	      editFields,
190	      editingTemplate,
191	      onUpdateTemplate,
192	      onCreateTemplate,
193	    ]);
194	
195	    // 复制模板
196	    const handleDuplicate = useCallback(
197	      async (template: FieldTemplate) => {
198	        await onDuplicateTemplate(template.id);
199	      },
200	      [onDuplicateTemplate],
201	    );
202	
203	    // 打开删除确认
204	    const handleOpenDeleteDialog = useCallback((template: FieldTemplate) => {
205	      setDeleteTarget(template);
206	      setIsDeleteDialogOpen(true);
207	    }, []);
208	
209	    // 确认删除
210	    const handleConfirmDelete = useCallback(async () => {
211	      if (!deleteTarget) return;
212	      await onDeleteTemplate(deleteTarget.id);
213	      setIsDeleteDialogOpen(false);
214	      setDeleteTarget(null);
215	    }, [deleteTarget, onDeleteTemplate]);
216	
217	    // 关闭时重置状态
218	    useEffect(() => {
219	      if (!open) {
220	        setSearchTerm('');
221	      }
222	    }, [open]);
223	
224	    return (
225	      <>
226	        <Dialog open={open} onOpenChange={onOpenChange}>
227	          <DialogContent className="sm:max-w-[500px]">
228	            <DialogHeader>
229	              <DialogTitle>字段模板管理</DialogTitle>
230	              <DialogDescription>
231	                管理可复用的字段模板，快速应用到表结构中
232	              </DialogDescription>
233	            </DialogHeader>
234	
235	            <div className="space-y-4">
236	              {/* 搜索和新建 */}
237	              <div className="flex gap-2">
238	                <div className="relative flex-1">
239	                  <Search className="absolute left-2.5 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
240	                  <Input
241	                    placeholder="搜索模板..."
242	                    value={searchTerm}
243	                    onChange={(e) => setSearchTerm(e.target.value)}
244	                    className="pl-8"
245	                  />
246	                </div>
247	                <Button onClick={() => handleOpenEditDialog()}>
248	                  <Plus className="mr-1 h-4 w-4" />
249	                  新建
250	                </Button>
251	              </div>
252	
253	              {/* 模板列表 */}
254	              <div className="max-h-[400px] space-y-2 overflow-y-auto">
255	                {loading ? (
256	                  <div className="py-8 text-center text-muted-foreground">
257	                    加载中...
258	                  </div>
259	                ) : filteredTemplates.length === 0 ? (
260	                  <div className="py-8 text-center text-muted-foreground">
261	                    {searchTerm
262	                      ? '未找到匹配的模板'
263	                      : '暂无模板，点击「新建」创建'}
264	                  </div>
265	                ) : (
266	                  filteredTemplates.map((template) => (
267	                    <TemplateListItem
268	                      key={template.id}
269	                      template={template}
270	                      onEdit={() => handleOpenEditDialog(template)}
271	                      onDuplicate={() => handleDuplicate(template)}
272	                      onDelete={() => handleOpenDeleteDialog(template)}
273	                    />
274	                  ))
275	                )}
276	              </div>
277	            </div>
278	
279	            <DialogFooter>
280	              <Button variant="outline" onClick={() => onOpenChange(false)}>
281	                关闭
282	              </Button>
283	            </DialogFooter>
284	          </DialogContent>
285	        </Dialog>
286	
287	        {/* 新建/编辑对话框 - 包含字段编辑器 */}
288	        <Dialog open={isEditDialogOpen} onOpenChange={setIsEditDialogOpen}>
289	          <DialogContent className="sm:max-w-[90vw] md:max-w-4xl lg:max-w-5xl max-h-[85vh] overflow-hidden flex flex-col">
290	            <DialogHeader>
291	              <DialogTitle>
292	                {editingTemplate ? '编辑模板' : '新建模板'}
293	              </DialogTitle>
294	              <DialogDescription>
295	                {editingTemplate
296	                  ? '修改模板名称、描述和字段'
297	                  : '创建一个新的字段模板'}
298	              </DialogDescription>
299	            </DialogHeader>
300	
301	            <div className="flex-1 overflow-y-auto space-y-4 py-4 min-h-0">
302	              {/* 基本信息 */}
