341	                </div>
342	
343	                {/* 表头 */}
344	                <div className="grid grid-cols-[24px_1.5fr_1.2fr_1.5fr_80px_1fr_1fr_1fr_28px] gap-2 px-2 text-[10px] uppercase tracking-wider font-semibold text-muted-foreground">
