  1	/**
  2	 * 从选中字段创建模板对话框
  3	 * 将用户选中的字段保存为可复用的模板
  4	 */
  5	
  6	import { memo, useState, useCallback, useEffect, useMemo } from 'react';
  7	import {
  8	  Dialog,
  9	  DialogContent,
 10	  DialogDescription,
 11	  DialogFooter,
 12	  DialogHeader,
 13	  DialogTitle,
 14	} from '@/components/ui/dialog';
 15	import { Button } from '@/components/ui/button';
 16	import { Input } from '@/components/ui/input';
 17	import { Label } from '@/components/ui/label';
 18	
 19	interface CreateTemplateDialogProps {
 20	  open: boolean;
 21	  onOpenChange: (open: boolean) => void;
 22	  selectedFields: Array<{
 23	    fieldName?: string;
 24	    fieldType?: string;
 25	    fieldComment?: string;
 26	    nullable?: string;
 27	    defaultKind?: string;
 28	    defaultValue?: string;
 29	    onUpdate?: string;
 30	  }>;
 31	  onConfirm: (
 32	    name: string,
 33	    fields: Array<{
 34	      fieldName?: string;
 35	      fieldType?: string;
 36	      fieldComment?: string;
 37	      nullable?: string;
 38	      defaultKind?: string;
 39	      defaultValue?: string;
 40	      onUpdate?: string;
 41	    }>,
 42	    description?: string,
 43	  ) => Promise<{ ok: boolean }>;
 44	}
 45	
 46	export const CreateTemplateDialog = memo<CreateTemplateDialogProps>(
 47	  ({ open, onOpenChange, selectedFields, onConfirm }) => {
 48	    const [name, setName] = useState('');
 49	    const [description, setDescription] = useState('');
 50	    const [error, setError] = useState('');
 51	    const [loading, setLoading] = useState(false);
 52	
 53	    // 过滤有效字段
 54	    const validFields = useMemo(
 55	      () => selectedFields.filter((f) => f.fieldName?.trim()),
 56	      [selectedFields],
 57	    );
 58	
 59	    // 重置状态
 60	    useEffect(() => {
 61	      if (open) {
 62	        setName('');
 63	        setDescription('');
 64	        setError('');
 65	        setLoading(false);
 66	      }
 67	    }, [open]);
 68	
 69	    const handleConfirm = useCallback(async () => {
 70	      const trimmedName = name.trim();
 71	      if (!trimmedName) {
 72	        setError('请输入模板名称');
 73	        return;
 74	      }
 75	
 76	      setLoading(true);
 77	      try {
 78	        const result = await onConfirm(
 79	          trimmedName,
 80	          validFields,
 81	          description.trim() || undefined,
 82	        );
 83	        if (result.ok) {
 84	          onOpenChange(false);
 85	        } else {
 86	          setError('创建失败');
 87	        }
 88	      } finally {
 89	        setLoading(false);
 90	      }
 91	    }, [name, description, validFields, onConfirm, onOpenChange]);
 92	
 93	    return (
 94	      <Dialog open={open} onOpenChange={onOpenChange}>
 95	        <DialogContent className="sm:max-w-[400px]">
 96	          <DialogHeader>
 97	            <DialogTitle>保存为模板</DialogTitle>
 98	            <DialogDescription>
 99	              将选中的 {validFields.length} 个字段保存为可复用的模板
100	            </DialogDescription>
101	          </DialogHeader>
102	
103	          <div className="grid gap-4 py-4">
104	            {/* 字段预览 */}
105	            <div className="rounded-md bg-muted p-3">
106	              <div className="text-sm font-medium mb-2">包含字段：</div>
107	              <div className="flex flex-wrap gap-1">
108	                {validFields.map((f, i) => (
109	                  <span
110	                    key={i}
111	                    className="inline-flex items-center rounded-md bg-background px-2 py-0.5 text-xs"
112	                  >
113	                    {f.fieldName}
114	                  </span>
115	                ))}
116	              </div>
117	            </div>
