  3	import { toast, type ExternalToast } from 'sonner';
  4	
  5	export interface UseToastReturn {
  6	  /**
  7	   * Show a success toast
  8	   */
  9	  success: (msg: string | React.ReactNode, options?: ExternalToast) => void;
 10	  /**
 11	   * Show an error toast
 12	   */
 13	  error: (msg: string | React.ReactNode, options?: ExternalToast) => void;
 14	  /**
 15	   * Show an info toast
 16	   */
 17	  info: (msg: string | React.ReactNode, options?: ExternalToast) => void;
 18	  /**
 19	   * Show a warning toast
 20	   */
 21	  warning: (msg: string | React.ReactNode, options?: ExternalToast) => void;
 22	  /**
 23	   * Show a promise toast
 24	   */
 25	  promise: <T>(
 26	    promise: Promise<T> | (() => Promise<T>),
 27	    data?: {
 28	      loading?: string | React.ReactNode;
 29	      success?:
 30	        | string
 31	        | React.ReactNode
 32	        | ((data: T) => string | React.ReactNode);
 33	      error?:
 34	        | string
 35	        | React.ReactNode
 36	        | ((error: any) => string | React.ReactNode);
 37	    },
 38	    options?: ExternalToast,
 39	  ) => void;
 40	  /**
 41	   * Generic toast message (default)
 42	   */
 43	  showToast: (msg: string | React.ReactNode, options?: ExternalToast) => void;
 44	  /**
 45	   * Dismiss a specific toast or all toasts
 46	   */
 47	  dismiss: (id?: string | number) => void;
 48	}
 49	
 50	export function useToast(): UseToastReturn {
 51	  const showToast = useCallback(
 52	    (msg: string | React.ReactNode, options?: ExternalToast) => {
 53	      toast(msg, options);
 54	    },
 55	    [],
 56	  );
 57	
 58	  const success = useCallback(
 59	    (msg: string | React.ReactNode, options?: ExternalToast) => {
 60	      toast.success(msg, options);
 61	    },
 62	    [],
 63	  );
 64	
 65	  const error = useCallback(
 66	    (msg: string | React.ReactNode, options?: ExternalToast) => {
 67	      toast.error(msg, options);
 68	    },
 69	    [],
 70	  );
 71	
 72	  const info = useCallback(
 73	    (msg: string | React.ReactNode, options?: ExternalToast) => {
 74	      toast.info(msg, options);
 75	    },
 76	    [],
 77	  );
 78	
 79	  const warning = useCallback(
 80	    (msg: string | React.ReactNode, options?: ExternalToast) => {
 81	      toast.warning(msg, options);
 82	    },
 83	    [],
 84	  );
 85	
 86	  const promise = useCallback(
 87	    <T>(
 88	      promise: Promise<T> | (() => Promise<T>),
 89	      data?: {
 90	        loading?: string | React.ReactNode;
 91	        success?:
 92	          | string
 93	          | React.ReactNode
 94	          | ((data: T) => string | React.ReactNode);
 95	        error?:
 96	          | string
 97	          | React.ReactNode
 98	          | ((error: any) => string | React.ReactNode);
 99	      },
100	      options?: ExternalToast,
101	    ) => {
102	      toast.promise(promise, { ...data, ...options });
103	    },
104	    [],
105	  );
106	
107	  const dismiss = useCallback((id?: string | number) => {
108	    toast.dismiss(id);
109	  }, []);
110	
111	  return {
112	    showToast,
113	    success,
114	    error,
115	    info,
116	    warning,
117	    promise,
118	    dismiss,
119	  };
120	}

