 54	  showToast,
 55	  trackEvent,
 56	}: UseSchemaApplyActionsParams) {
 57	  const handleApplySuggestion = useCallback(
 58	    (suggestion: StructuredSuggestion) => {
 59	      if (suggestion.applied) return;
 60	
 61	      let appliedCount = 0;
 62	      let newIndexId: string | null = null;
 63	
 64	      if (
 65	        suggestion.type === 'add_index' ||
 66	        suggestion.type === 'remove_index'
 67	      ) {
 68	        setActiveTab('indexes');
 69	      } else if (
 70	        suggestion.type === 'add_field' ||
 71	        suggestion.type === 'modify_field' ||
 72	        suggestion.type === 'remove_field'
 73	      ) {
 74	        setActiveTab('fields');
 75	      }
 76	
 77	      switch (suggestion.type) {
 78	        case 'add_field':
 79	          if (suggestion.field) {
 80	            const newRow: FieldRow = {
 81	              order: rows.length + 1,
 82	              fieldName: suggestion.field.fieldName,
 83	              fieldType: suggestion.field.fieldType,
 84	              fieldComment: suggestion.field.fieldComment || '',
 85	              nullable: suggestion.field.nullable || '是',
 86	              defaultKind: suggestion.field.defaultKind || '无',
 87	              defaultValue: suggestion.field.defaultValue || '',
 88	              onUpdate: suggestion.field.onUpdate || '无',
 89	            };
 90	            setRows((prev) => [...prev, newRow]);
 91	            appliedCount = 1;
 92	            triggerFieldTableHighlight(rows.length);
 93	          }
 94	          break;
 95	
 96	        case 'modify_field':
 97	          if (suggestion.fieldModification) {
 98	            const { fieldName } = suggestion.fieldModification;
 99	            const changes = suggestion.fieldModification.changes || {
100	              fieldType: suggestion.fieldModification.fieldType,
101	              fieldComment: suggestion.fieldModification.fieldComment,
102	              nullable: suggestion.fieldModification.nullable,
103	              defaultKind: suggestion.fieldModification.defaultKind,
104	              defaultValue: suggestion.fieldModification.defaultValue,
105	              onUpdate: suggestion.fieldModification.onUpdate,
106	            };
107	            const rowIndex = rows.findIndex(
108	              (row) => row.fieldName === fieldName,
109	            );
110	            if (rowIndex !== -1) {
111	              const filteredChanges = Object.fromEntries(
112	                Object.entries(changes).filter(
113	                  ([, value]) => value !== undefined,
114	                ),
115	              );
116	              setRows((prev) => {
117	                const updatedRows = [...prev];
118	                updatedRows[rowIndex] = {
119	                  ...updatedRows[rowIndex],
120	                  ...filteredChanges,
121	                };
122	                return updatedRows;
123	              });
124	              appliedCount = 1;
125	              triggerFieldTableHighlight(rowIndex);
126	            }
127	          }
128	          break;
129	
130	        case 'remove_field':
131	          if (suggestion.fieldName) {
132	            const rowIndex = rows.findIndex(
133	              (row) => row.fieldName === suggestion.fieldName,
134	            );
135	            if (rowIndex !== -1) {
136	              triggerFieldTableHighlight(rowIndex);
137	              setTimeout(() => {
138	                setRows((prev) => {
139	                  const newRows = prev.filter(
140	                    (row) => row.fieldName !== suggestion.fieldName,
141	                  );
142	                  return newRows.map((row, index) => ({
143	                    ...row,
144	                    order: index + 1,
145	                  }));
146	                });
147	              }, 500);
148	              appliedCount = 1;
149	            }
150	          }
151	          break;
152	
153	        case 'add_index':
154	          if (suggestion.index) {
155	            newIndexId = `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
156	            const newIndex: IndexDefinition = {
157	              id: newIndexId,
158	              name: suggestion.index.name,
159	              fields: suggestion.index.fields,
160	              unique: !!suggestion.index.unique,
161	            };
162	            setIndexes((prev) => [...prev, newIndex]);
163	            appliedCount = 1;
164	            setTimeout(() => {
165	              if (newIndexId) {
166	                triggerIndexAnimation(newIndexId, 'add');
167	              }
168	            }, 50);
169	          }
170	          break;
171	
172	        case 'remove_index':
173	          if (suggestion.indexName) {
174	            const targetIndex = indexes.find(
175	              (index) => index.name === suggestion.indexName,
176	            );
177	            if (targetIndex) {
178	              triggerIndexAnimation(targetIndex.id, 'remove');
179	              setTimeout(() => {
180	                setIndexes((prev) =>
181	                  prev.filter((index) => index.name !== suggestion.indexName),
182	                );
183	              }, 500);
184	              appliedCount = 1;
185	            }
186	          }
187	          break;
188	
189	        default:
190	          break;
191	      }
192	
193	      if (appliedCount > 0 && reviewResult) {
194	        const newSuggestions = reviewResult.suggestions.map((item) => {
195	          if (typeof item !== 'string' && item.id === suggestion.id) {
196	            return { ...item, applied: true };
197	          }
198	          return item;
199	        });
200	        setReviewResult({ ...reviewResult, suggestions: newSuggestions });
