206	      }
207	    },
208	    [
209	      rows,
210	      indexes,
211	      reviewResult,
212	      setRows,
213	      setIndexes,
214	      setReviewResult,
215	      showToast,
216	      trackEvent,
217	      triggerIndexAnimation,
218	      triggerFieldTableHighlight,
