220	    ],
221	  );
222	
223	  const handleImport = useCallback(
224	    (result: ParsedResult, importDbType: DatabaseType) => {
225	      setTableName(result.tableName);
226	      setTableComment(result.tableComment);
227	      setDbType(importDbType);
228	
229	      const newRows: FieldRow[] = result.fields.map((field, index) => {
230	        let uiNullable = '是';
231	        if (field.nullable === false) uiNullable = '否';
232	
233	        let uiDefaultKind: NullableDefault = '无';
234	        switch (field.defaultKind) {
235	          case 'auto_increment':
236	            uiDefaultKind = '自增';
237	            break;
238	          case 'constant':
239	            uiDefaultKind = '常量';
240	            break;
241	          case 'current_timestamp':
242	            uiDefaultKind = '当前时间';
243	            break;
244	          case 'uuid':
245	            uiDefaultKind = 'uuid';
246	            break;
247	          default:
248	            uiDefaultKind = '无';
249	            break;
250	        }
251	
252	        let uiOnUpdate: NullableDefault = '无';
253	        if (field.onUpdate === 'current_timestamp') {
254	          uiOnUpdate = '当前时间';
255	        }
256	
257	        return {
258	          order: index + 1,
259	          fieldName: field.name,
260	          fieldType: field.type,
261	          fieldComment: field.comment,
262	          nullable: uiNullable,
263	          defaultKind: uiDefaultKind,
264	          defaultValue: field.defaultValue,
265	          onUpdate: uiOnUpdate,
266	        };
267	      });
268	
269	      const minRows = 12;
270	      if (newRows.length < minRows) {
271	        for (let i = newRows.length; i < minRows; i += 1) {
272	          newRows.push(createEmptyRow(i));
