279	
280	      setAuthObjects(result.authObjects);
281	      setAuthInput('');
282	      trackEvent('sql_import', { dbType: importDbType });
283	    },
284	    [
285	      setRows,
286	      setIndexes,
287	      setAuthObjects,
288	      setIndexInput,
289	      setAuthInput,
290	      setTableName,
291	      setTableComment,
292	      setDbType,
293	      trackEvent,
294	    ],
295	  );
296	
297	  const handleApplyAIGeneratedSchema = useCallback(
298	    (schema: GeneratedTableSchema) => {
299	      if (schema.tableName) {
300	        setTableName(schema.tableName);
301	      }
302	      if (schema.tableComment) {
303	        setTableComment(schema.tableComment);
304	      }
305	
306	      if (schema.fields && schema.fields.length > 0) {
307	        const newRows = schema.fields.map((field, index) => ({
308	          order: index + 1,
309	          fieldName: field.fieldName,
310	          fieldType: field.fieldType,
311	          fieldComment: field.fieldComment,
312	          nullable: field.nullable,
313	          defaultKind: field.defaultKind,
314	          defaultValue: field.defaultValue || '',
315	          onUpdate: field.onUpdate || '无',
316	        }));
317	        setRows(newRows as FieldRow[]);
318	      }
319	
320	      if (schema.indexes && schema.indexes.length > 0) {
321	        const newIndexes = schema.indexes.map((index, i) => ({
322	          id: `ai-${Date.now()}-${i}`,
