332	            name: field.fieldName,
333	            direction: 'ASC' as const,
334	          }));
335	
336	        if (pkFields && pkFields.length > 0) {
337	          newIndexes.unshift({
338	            id: `pk-${Date.now()}`,
339	            name: 'PRIMARY',
340	            fields: pkFields,
341	            unique: true,
342	            isPrimary: true,
343	          });
344	        }
345	
346	        setIndexes(newIndexes as IndexDefinition[]);
347	      }
348	
349	      trackEvent('ai_generate_apply', { tableName: schema.tableName });
