 64	    } catch {
 65	      try {
 66	        const ta = document.createElement('textarea');
 67	        ta.value = text;
 68	        ta.style.position = 'fixed';
 69	        ta.style.left = '-9999px';
 70	        document.body.appendChild(ta);
 71	        ta.select();
 72	        document.execCommand('copy');
 73	        document.body.removeChild(ta);
 74	        return true;
 75	      } catch {
 76	        return false;
 77	      }
 78	    }
 79	  }, [generatedSql]);
 80	
 81	  const copyDcl = useCallback(async () => {
 82	    const text = generatedDcl || '-- 请在下方配置授权对象';
 83	    try {
 84	      await navigator.clipboard.writeText(text);
 85	      return true;
 86	    } catch {
 87	      try {
 88	        const ta = document.createElement('textarea');
 89	        ta.value = text;
 90	        ta.style.position = 'fixed';
 91	        ta.style.left = '-9999px';
